class Car {
    String brand;
    Car(String brand) { this.brand = brand; }
}

class ElectricCar extends Car {
    int batteryLevel;
    ElectricCar(String brand, int batteryLevel) {
        super(brand);
        this.batteryLevel = batteryLevel;
    }
}
// Test: new ElectricCar("Tesla", 100).brand → "Tesla"

